package tn.supcom.greenpilot.api.controllers.repositories;

import jakarta.data.repository.BasicRepository;
import jakarta.data.repository.Repository;
import tn.supcom.greenpilot.api.entities.Measurement;

import java.util.List;

/** Jakarta Data repository; implementation generated by Eclipse JNoSQL. */
@Repository
public interface MeasurementRepository
        extends BasicRepository<Measurement, String> {

    /** Returns all measurements belonging to the specified site. */
    List<Measurement> findBySiteId(String siteId);
}
